class Solution {
    fun minSideJumps(obstacles:IntArray):Int{
        val inf=1_000_000;
        val dp=intArrayOf(1,0,1);
        for(position in 1 until obstacles.size){
            if(obstacles[position]>0)dp[obstacles[position]-1]=inf;
            val minimum=dp.minOrNull()!!;
            for(lane in 0 until 3)if(obstacles[position]!=lane+1)dp[lane]=minOf(dp[lane],minimum+1)
        };
        return dp.minOrNull()!!
    }
}

code.cpp:
class Solution {
    public: int minSideJumps(vector<int>& obstacles){
        const int inf=1000000;
        int dp[3]={
            1,0,1
        };
        for(int position=1;position<(int)obstacles.size();++position){
            if(obstacles[position])dp[obstacles[position]-1]=inf;
            int minimum=min({
                dp[0],dp[1],dp[2]
            });
            for(int lane=0;lane<3;++lane)if(obstacles[position]!=lane+1)dp[lane]=min(dp[lane],minimum+1);
        }
        return min({
            dp[0],dp[1],dp[2]
        });
    }
};
